using Microsoft.EntityFrameworkCore;

namespace AsisQR.Api.Data;

public static class Esquema
{
    public static void Aplicar(AppDb db)
    {
        db.Database.ExecuteSqlRaw("""
            ALTER TABLE "Estudiantes" ADD COLUMN IF NOT EXISTS "Foto" bytea;
            ALTER TABLE "Estudiantes" ADD COLUMN IF NOT EXISTS "FotoTipo" character varying(40);
            ALTER TABLE "Asistencias" ADD COLUMN IF NOT EXISTS "Origen" character varying(20) NOT NULL DEFAULT 'Qr';

            CREATE TABLE IF NOT EXISTS "Directores" (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "Nombre" character varying(120) NOT NULL,
                "Usuario" character varying(40) NOT NULL,
                "PasswordHash" text NOT NULL
            );
            CREATE UNIQUE INDEX IF NOT EXISTS "IX_Directores_Usuario" ON "Directores" ("Usuario");

            CREATE TABLE IF NOT EXISTS "Rostros" (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "EstudianteId" integer NOT NULL REFERENCES "Estudiantes"("Id") ON DELETE CASCADE,
                "Pose" character varying(20) NOT NULL,
                "Vector" text NOT NULL
            );
            CREATE UNIQUE INDEX IF NOT EXISTS "IX_Rostros_Estudiante_Pose" ON "Rostros" ("EstudianteId", "Pose");

            CREATE TABLE IF NOT EXISTS "NotaColumnas" (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "MateriaId" integer NOT NULL REFERENCES "Materias"("Id") ON DELETE CASCADE,
                "GrupoId" integer NOT NULL REFERENCES "Grupos"("Id") ON DELETE CASCADE,
                "Nombre" character varying(80) NOT NULL,
                "Orden" integer NOT NULL
            );
            CREATE UNIQUE INDEX IF NOT EXISTS "IX_NotaColumnas_Materia_Grupo_Nombre"
                ON "NotaColumnas" ("MateriaId", "GrupoId", "Nombre");

            CREATE TABLE IF NOT EXISTS "Notas" (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "ColumnaId" integer NOT NULL REFERENCES "NotaColumnas"("Id") ON DELETE CASCADE,
                "EstudianteId" integer NOT NULL REFERENCES "Estudiantes"("Id") ON DELETE CASCADE,
                "Valor" numeric(5,2) NOT NULL
            );
            CREATE UNIQUE INDEX IF NOT EXISTS "IX_Notas_Columna_Estudiante" ON "Notas" ("ColumnaId", "EstudianteId");
            """);
    }
}
